pipeline {
  agent {
    kubernetes {
      serviceAccount 'jenkins-cluster-admin'
      yaml """
spec:
  containers:
  - name: node
    image: node@sha256:1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2c
    command: ['sleep', 'infinity']
"""
    }
  }
  stages {
    stage('Unit tests') {
      steps { container('node') { sh 'npm ci && npm test' } }
    }
  }
}

@Library('shared-pipeline@master') _

pipeline {
  agent { label 'linux' }
  stages {
    stage('Build') {
      steps { sh './gradlew build' }
    }
    stage('Publish') {
      when { branch 'main' }
      steps { publishToNexus(repo: 'releases') }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Deploy') {
      when { branch 'main' }
      steps {
        withCredentials([usernamePassword(credentialsId: 'artifactory', usernameVariable: 'ART_USER', passwordVariable: 'ART_PASS')]) {
          sh "curl -fsS -u ${ART_USER}:${ART_PASS} -T build/app.zip https://artifactory.example.com/libs-release/app.zip"
        }
      }
    }
  }
}

pipeline {
  agent {
    kubernetes {
      yaml """
spec:
  containers:
  - name: builder
    image: ghcr.io/example/builder@sha256:4c6e8a0b2d4f6a8c0e2b4d6f8a0c2e4b6d8f0a2c4e6b8d0f2a4c6e8b0d2f4a6c
    command: ['sleep', 'infinity']
    securityContext:
      privileged: true
"""
    }
  }
  stages {
    stage('Build') {
      steps { container('builder') { sh 'make image' } }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Release') {
      when { tag 'v*' }
      steps {
        withMaven(mavenSettingsConfig: 'release-settings') {
          sh 'mvn -B -ntp deploy -DskipTests -Dgpg.skip=true'
        }
      }
    }
  }
}

